def write(path, html):
    p=root/path;p.mkdir(parents=True,exist_ok=True);(p/'index.html').write_text(html,encoding='utf-8')

def subhero(kicker,title,lead,cta='Hablemos',cta_url='/contacto/'):
    return f'''<section class="subhero"><div class="container subhero-grid"><div class="reveal"><p class="eyebrow shiny">{kicker}</p><h1>{title}</h1><p class="lead">{lead}</p><div class="actions"><a class="btn btn-primary magnetic star-border" href="{cta_url}">{cta} ↗</a><a class="btn btn-secondary magnetic" href="#servicios">Ver soluciones ↓</a></div></div><div class="visual-orb reveal" data-tilt="4"><span class="ring r1"></span><span class="ring r2"></span><span class="ring r3"></span><div class="core"></div></div></div></section>'''

def cards(items):
    out='<div class="grid-3">'
    for i,(icon,title,text,url) in enumerate(items,1):
        out+=f'''<article class="card spotlight reveal" data-tilt="3"><span class="num">{i:02d}</span><div class="card-icon">{icon}</div><h3>{title}</h3><p>{text}</p><a href="{url}">Saber mas <span>↗</span></a></article>'''
    return out+'</div>'

def section(title,lead,body,kicker='FENUALV',dark=False):
    cls='section ai-zone' if dark else 'section'
    return f'''<section class="{cls}" id="servicios"><div class="container"><div class="section-head reveal"><div><p class="eyebrow">{kicker}</p><h2>{title}</h2></div><p>{lead}</p></div>{body}</div></section>'''

